/** Static curriculum data (generated by backend/scripts/import_learn.py). */
const memo = new Map();

function load(path) {
  if (!memo.has(path)) {
    const p = fetch(`data/learn/${path}`).then((r) => {
      if (!r.ok) throw new Error(`تعذّر تحميل ${path}`);
      return r.json();
    });
    p.catch(() => memo.delete(path));
    memo.set(path, p);
  }
  return memo.get(path);
}

export const learnData = {
  index: () => load("index.json"),
  lesson: (slug) => load(`lessons/${encodeURIComponent(slug)}.json`),
  practice: () => load("practice.json"),
  mutun: () => load("mutun.json"),
  cheatsheet: () => load("cheatsheet.json"),
  /** Lines of a matn by number, e.g. cite("tuhfah", [14, 15]). */
  async cite(text, lines) {
    const m = (await load("mutun.json")).find((x) => x.key === text);
    if (!m) return null;
    const want = new Set(lines);
    return { title: m.title, key: m.key, lines: m.sections.flatMap((s) => s.lines).filter((l) => want.has(l.n)) };
  },
};

const DONE_KEY = "hifz.learn.done";
export const progress = {
  get() { try { return new Set(JSON.parse(localStorage.getItem(DONE_KEY) || "[]")); } catch { return new Set(); } },
  set(slug, done) {
    const s = this.get();
    done ? s.add(slug) : s.delete(slug);
    try { localStorage.setItem(DONE_KEY, JSON.stringify([...s])); } catch { /* storage unavailable */ }
  },
};
